:root {
  --bg: #1e1e2f;
  --surface: #2a2a40;
  --primary: #6c63ff;
  --primary-hover: #5a52d5;
  --accent: #ff6584;
  --text: #f0f0f0;
  --text-muted: #a0a0b8;
  --card-back: #3a3a55;
  --card-radius: 12px;
  --gap: 12px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 18px;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 20px;
}

.game-container {
  background: var(--surface);
  padding: 28px 24px;
  border-radius: 20px;
  box-shadow: 0 12px 32px rgba(0, 0, 0, 0.4);
  max-width: 600px;
  width: 100%;
  text-align: center;
}

h1 {
  font-size: 1.8rem;
  margin-bottom: 6px;
  color: var(--primary);
}

.subtitle {
  color: var(--text-muted);
  font-size: 1rem;
  margin-bottom: 20px;
}

.stats {
  display: flex;
  justify-content: center;
  gap: 32px;
  font-size: 1.1rem;
  margin-bottom: 20px;
  color: var(--text-muted);
}

.stats strong {
  color: var(--text);
}

.game-board {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--gap);
  margin-bottom: 20px;
}

.card {
  aspect-ratio: 1 / 1;
  border-radius: var(--card-radius);
  background: var(--card-back);
  cursor: pointer;
  position: relative;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
  border: 2px solid transparent;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  color: transparent;
  user-select: none;
  overflow: hidden;
}

.card:hover {
  transform: scale(1.04);
  box-shadow: 0 0 0 3px var(--primary);
}

.card:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.card.flipped {
  background: var(--color);
  color: #fff;
  cursor: default;
  transform: scale(1);
}

.card.matched {
  background: var(--color);
  color: #fff;
  cursor: default;
  opacity: 0.7;
  transform: scale(0.95);
  box-shadow: inset 0 0 0 3px rgba(255,255,255,0.3);
}

.card.matched::after {
  content: '✓';
  font-size: 2rem;
  font-weight: bold;
}

.win-message {
  font-size: 1.3rem;
  font-weight: bold;
  color: var(--accent);
  min-height: 2rem;
  margin-bottom: 12px;
}

.new-game-btn {
  background: var(--primary);
  color: #fff;
  border: none;
  border-radius: 10px;
  padding: 12px 32px;
  font-size: 1.1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
  font-family: inherit;
}

.new-game-btn:hover {
  background: var(--primary-hover);
}

.new-game-btn:active {
  transform: scale(0.96);
}

.new-game-btn:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 3px;
}

@media (max-width: 480px) {
  .game-container {
    padding: 20px 14px;
  }
  h1 {
    font-size: 1.4rem;
  }
  .game-board {
    gap: 8px;
  }
  .stats {
    gap: 20px;
    font-size: 1rem;
  }
  .new-game-btn {
    padding: 10px 24px;
    font-size: 1rem;
  }
}

const COLORS = [
  '#e63946', '#f4a261', '#2a9d8f', '#457b9d',
  '#9b5de5', '#f15bb5', '#00bbf9', '#00f5d4'
];

const board = document.getElementById('game-board');
const moveCountEl = document.getElementById('move-count');
const matchCountEl = document.getElementById('match-count');
const winMessage = document.getElementById('win-message');
const newGameBtn = document.getElementById('new-game-btn');

let cards = [];
let flipped = [];
let matched = 0;
let moves = 0;
let lock = false;

function shuffle(arr) {
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return arr;
}

function createBoard() {
  const pairColors = [...COLORS, ...COLORS];
  cards = shuffle(pairColors.map((color, i) => ({
    id: i,
    color,
    matched: false
  })));
  renderBoard();
}

function renderBoard() {
  board.innerHTML = '';
  cards.forEach((card, index) => {
    const el = document.createElement('button');
    el.className = 'card';
    el.dataset.index = index;
    el.setAttribute('aria-label', `Card ${index + 1}, hidden`);
    el.style.setProperty('--color', card.color);
    el.addEventListener('click', () => flipCard(index));
    board.appendChild(el);
  });
}

function flipCard(index) {
  if (lock) return;
  const card = cards[index];
  const el = board.children[index];
  if (card.matched || el.classList.contains('flipped')) return;

  el.classList.add('flipped');
  el.setAttribute('aria-label', `Card ${index + 1}, revealed`);
  flipped.push(index);

  if (flipped.length === 2) {
    moves++;
    moveCountEl.textContent = moves;
    checkMatch();
  }
}

function checkMatch() {
  const [i, j] = flipped;
  const card1 = cards[i];
  const card2 = cards[j];
  const el1 = board.children[i];
  const el2 = board.children[j];

  if (card1.color === card2.color) {
    card1.matched = card2.matched = true;
    el1.classList.add('matched');
    el2.classList.add('matched');
    el1.setAttribute('aria-label', `Card ${i + 1}, matched`);
    el2.setAttribute('aria-label', `Card ${j + 1}, matched`);
    matched++;
    matchCountEl.textContent = matched;
    flipped = [];
    if (matched === 8) {
      winMessage.textContent = `You won in ${moves} moves! 🎉`;
    }
  } else {
    lock = true;
    setTimeout(() => {
      el1.classList.remove('flipped');
      el2.classList.remove('flipped');
      el1.setAttribute('aria-label', `Card ${i + 1}, hidden`);
      el2.setAttribute('aria-label', `Card ${j + 1}, hidden`);
      flipped = [];
      lock = false;
    }, 800);
  }
}

function newGame() {
  flipped = [];
  matched = 0;
  moves = 0;
  lock = false;
  moveCountEl.textContent = '0';
  matchCountEl.textContent = '0';
  winMessage.textContent = '';
  createBoard();
}

newGameBtn.addEventListener('click', newGame);

createBoard();
